"use client";
import React, { useState } from "react";
import { FcGoogle } from "react-icons/fc";
import { IoEyeOutline } from "react-icons/io5";
import { useRouter } from "next/router"; // Import useRouter
// import {
//   createUserWithEmailAndPassword,
//   signInWithEmailAndPassword,
//   signInWithPopup,
// } from "firebase/auth";
// import { auth } from "../../../firebase/firebase";
// import { GoogleAuthProvider } from "firebase/auth/web-extension";

function RegisterPage() {
  //   const [email, setEmail] = useState("");
  //   const [password, setPassword] = useState("");
  const [isLogin, setIsLogin] = useState(true);
  const router = useRouter(); // Initialize router
  const toggleAuthMode = () => {
    setIsLogin((prev) => {
      const newIsLogin = !prev;

      // Navigate to /signup or /login based on the new state
      router.push(newIsLogin ? "/login" : "/signup");

      return newIsLogin;
    });
  };
  //   const handleAuth = async () => {
  //     try {
  //       if (isLogin) {
  //         await signInWithEmailAndPassword(auth, email, password);
  //       } else {
  //         await createUserWithEmailAndPassword(auth, email, password);
  //       }
  //     } catch (error) {
  //       console.error(error);
  //     }
  //   };

  //   const handleGoogleSignIn = async () => {
  //     const provider = new GoogleAuthProvider();
  //     try {
  //       await signInWithPopup(auth, provider);
  //     } catch (error) {
  //       console.error(error);
  //     }
  //   };

  return (
    <div className="h-screen flex flex-col items-center justify-center bg-gradient-to-r from-green-100 via-purple-100 to-purple-200">
      {/* Header */}
      <div className="absolute top-0 left-0 w-full flex justify-between items-center px-8 py-4">
        <div className="text-2xl font-bold">Gradient</div>
        <div className="flex space-x-2">
          <button
            className={`px-4 py-2 rounded-l-full ${
              isLogin ? "bg-gray-800 text-white" : "bg-gray-200"
            }`}
            onClick={() => {
              setIsLogin(true);
              router.push("/login");
            }} // Navigate to /login
          >
            Log In
          </button>
          <button
            className={`px-4 py-2 rounded-r-full ${
              !isLogin ? "bg-gray-800 text-white" : "bg-gray-200"
            }`}
            onClick={() => {
              setIsLogin(false);
              router.push("/signup"); // Navigate to /signup
            }}
          >
            Sign Up
          </button>
        </div>
      </div>

      {/* Form */}
      <div className="w-full max-w-md bg-white rounded-lg shadow-lg p-8">
        <h2 className="text-2xl font-semibold text-center">
          {isLogin ? "Log In" : "Sign Up"}
        </h2>
        <p className="text-center text-gray-500 mt-2">
          {isLogin
            ? "Welcome back! Log in to stay updated with all your nodes and rewards."
            : "Start your journey on Gradient Network and shape the future of compute."}
        </p>
        <form className="space-y-4 mt-6">
          {/* Email */}
          <div>
            <label className="block text-sm font-medium text-gray-700">
              Email
            </label>
            <input
              type="email"
              placeholder="Enter Email"
              className="mt-1 block w-full px-4 py-2 border border-gray-300 rounded-lg shadow-sm focus:ring focus:ring-opacity-50"
            />
          </div>

          {/* Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700">
              Password
            </label>
            <div className="relative">
              <input
                type="password"
                placeholder="Enter Password"
                className="mt-1 block w-full px-4 py-2 border border-gray-300 rounded-lg shadow-sm focus:ring focus:ring-opacity-50"
              />
              <span className="absolute inset-y-0 right-0 flex items-center pr-3 cursor-pointer text-gray-500">
                <IoEyeOutline />
              </span>
            </div>
          </div>

          {/* Forgot Password */}
          <div className="text-right text-sm text-gray-500 hover:underline">
            <a href="#">Forgot Password</a>
          </div>

          {/* Buttons */}
          <button
            type="button"
            className="w-full bg-black text-white py-2 px-4 rounded-lg hover:bg-gray-800"
          >
            {isLogin ? "Log In" : "Sign Up"}
          </button>

          {/* Google Sign In */}
          <button
            type="button"
            className="w-full border border-gray-300 text-black py-2 px-4 rounded-lg flex items-center justify-center space-x-2 hover:bg-gray-100"
          >
            <FcGoogle />
            <span>Sign in with Google</span>
          </button>
        </form>

        {/* Switch between Log In and Sign Up */}
        <p className="mt-6 text-center text-sm text-gray-500">
          {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
          <button
            type="button"
            className="text-blue-500 hover:underline"
            onClick={toggleAuthMode}
          >
            {isLogin ? "Sign Up" : "Log In"}
          </button>
        </p>
      </div>
    </div>
  );
}

export default RegisterPage;
